1: // The root package.json version is the single source of truth (REQ-REL-103). This writes it into cli/package.json,
2: // cli/package-lock.json, core/Cargo.toml and core/Cargo.lock; `--check` only reports drift and exits 1 when any file
3: // disagrees (run in CI and the release workflow). `--tag vX.Y.Z` additionally requires the tag to match.
4: import fs from "node:fs";
5: import path from "node:path";
6: import { fileURLToPath } from "node:url";
7: 
8: const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
9: const args = process.argv.slice(2);
10: const check = args.includes("--check");
11: const tagIndex = args.indexOf("--tag");
12: const tag = tagIndex >= 0 ? args[tagIndex + 1] : undefined;
13: 
14: const version = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8")).version;
15: if (!/^\d+\.\d+\.\d+(-[0-9A-Za-z.]+)?$/.test(version)) throw new Error(`package.json version '${version}' is not SemVer`);
16: 
17: const drift = [];
18: const update = (rel, transform) => {
19:   const file = path.join(root, rel);
20:   const before = fs.readFileSync(file, "utf8");
21:   const after = transform(before);
22:   if (after === before) return;
23:   drift.push(rel);
24:   if (!check) fs.writeFileSync(file, after);
25: };
26: 
27: const jsonVersion = (text, paths) => {
28:   const data = JSON.parse(text);
29:   for (const p of paths) {
30:     let node = data;
31:     for (const key of p.slice(0, -1)) node = node?.[key];
32:     if (node && typeof node === "object" && p[p.length - 1] in node) node[p[p.length - 1]] = version;
33:   }
34:   return JSON.stringify(data, null, 2) + "\n";
35: };
36: 
37: update("cli/package.json", (t) => jsonVersion(t, [["version"]]));
38: update("cli/package-lock.json", (t) => jsonVersion(t, [["version"], ["packages", "", "version"]]));
39: update("core/Cargo.toml", (t) => t.replace(/^(\[package\][^[]*?\nversion = )"[^"]*"/s, `$1"${version}"`));
40: update("core/Cargo.lock", (t) => t.replace(/(\[\[package\]\]\nname = "harness-core"\nversion = )"[^"]*"/, `$1"${version}"`));
41: 
42: if (tag !== undefined && tag !== `v${version}`) {
43:   console.error(`tag ${tag} does not match package.json version ${version}`);
44:   process.exit(1);
45: }
46: if (drift.length) {
47:   console.error(`${check ? "version drift" : "updated to " + version}: ${drift.join(", ")}`);
48:   if (check) process.exit(1);
49: } else {
50:   console.log(`all components at ${version}`);
51: }

