#!/usr/bin/env node
import http from "node:http";
import fs from "node:fs";

const PORT = parseInt(process.env.MOCK_PORT || process.argv[2] || "19280", 10);

let mode = "normal";
let step = 0;
const recordedRequests = [];

const server = http.createServer((req, res) => {
  const url = req.url || "/";
  let body = "";

  req.on("data", chunk => {
    body += chunk;
  });

  req.on("end", () => {
    recordedRequests.push({
      method: req.method,
      url,
      headers: req.headers,
      body: body ? (tryParseJson(body) || body) : null,
      timestamp: Date.now()
    });

    // Control endpoints
    if (url === "/control/set-mode" && req.method === "POST") {
      try {
        const payload = JSON.parse(body);
        mode = payload.mode || "normal";
        step = 0;
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ ok: true, mode, step }));
        return;
      } catch (err) {
        res.writeHead(400, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: err.message }));
        return;
      }
    }

    if (url === "/control/requests" && req.method === "GET") {
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ count: recordedRequests.length, requests: recordedRequests }));
      return;
    }

    if (url === "/control/reset" && req.method === "POST") {
      recordedRequests.length = 0;
      mode = "normal";
      step = 0;
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ ok: true }));
      return;
    }

    // OpenAI Protocol Endpoints
    if (url.startsWith("/v1/models") || url.startsWith("/models")) {
      if (mode === "auth_401") {
        res.writeHead(401, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: { message: "Incorrect API key provided: " + (req.headers.authorization || "none"), type: "invalid_request_error", code: "invalid_api_key" } }));
        return;
      }
      if (mode === "auth_403") {
        res.writeHead(403, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: { message: "Forbidden: Account suspended or access revoked", type: "permission_error", code: "permission_denied" } }));
        return;
      }
      if (mode === "error_500") {
        res.writeHead(500, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: { message: "Internal server error" } }));
        return;
      }
      if (mode === "timeout") {
        // Do not respond; let caller time out
        return;
      }

      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(JSON.stringify({
        object: "list",
        data: [
          {
            id: "mock-qwen",
            object: "model",
            created: 1730000000,
            owned_by: "nexus-qa"
          }
        ]
      }));
      return;
    }

    if (url.startsWith("/v1/chat/completions") || url.startsWith("/chat/completions")) {
      if (mode === "auth_401") {
        res.writeHead(401, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: { message: "Incorrect API key provided", type: "invalid_request_error", code: "invalid_api_key" } }));
        return;
      }
      if (mode === "auth_403") {
        res.writeHead(403, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: { message: "Forbidden: Access denied", type: "permission_error", code: "permission_denied" } }));
        return;
      }
      if (mode === "rate_limit_429") {
        res.writeHead(429, { "Content-Type": "application/json", "retry-after": "2" });
        res.end(JSON.stringify({ error: { message: "Rate limit reached for requests", type: "rate_limit_error", code: "rate_limit_exceeded" } }));
        return;
      }
      if (mode === "error_500") {
        res.writeHead(500, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: { message: "Server overloaded" } }));
        return;
      }
      if (mode === "timeout") {
        return;
      }

      // Check if client requested streaming SSE
      const isStream = body && body.includes('"stream":true');
      step++;

      let toolCalls = [];
      let content = "Proceeding with next step.";

      if (step === 1) {
        content = "Inspecting workspace README.";
        toolCalls = [{
          id: "call_read_1",
          type: "function",
          function: {
            name: "read_file",
            arguments: JSON.stringify({ path: "README.md" })
          }
        }];
      } else if (step === 2) {
        content = "Writing verified implementation.";
        toolCalls = [{
          id: "call_write_1",
          type: "function",
          function: {
            name: "write_file",
            arguments: JSON.stringify({
              path: "src/feature.js",
              content: "// Verified implementation for QA\nexport function run() { return 42; }\n"
            })
          }
        }];
      } else if (step === 3) {
        content = "Executing verification check.";
        toolCalls = [{
          id: "call_cmd_1",
          type: "function",
          function: {
            name: "run_command",
            arguments: JSON.stringify({ command: "node -e 'console.log(\"CHECK PASS\")'" })
          }
        }];
      } else {
        content = "Task successfully completed.";
        toolCalls = [{
          id: "call_done_1",
          type: "function",
          function: {
            name: "task_completed",
            arguments: JSON.stringify({ summary: "Implementation verified and checks passed" })
          }
        }];
      }

      if (isStream) {
        res.writeHead(200, {
          "Content-Type": "text/event-stream",
          "Cache-Control": "no-cache",
          "Connection": "keep-alive"
        });

        // Send initial chunk
        const chunk1 = {
          id: `chatcmpl-${step}`,
          object: "chat.completion.chunk",
          created: Math.floor(Date.now() / 1000),
          model: "mock-qwen",
          choices: [{
            index: 0,
            delta: { role: "assistant", content },
            finish_reason: null
          }]
        };
        res.write(`data: ${JSON.stringify(chunk1)}\n\n`);

        if (toolCalls.length > 0) {
          const tc = toolCalls[0];
          const chunk2 = {
            id: `chatcmpl-${step}`,
            object: "chat.completion.chunk",
            created: Math.floor(Date.now() / 1000),
            model: "mock-qwen",
            choices: [{
              index: 0,
              delta: {
                tool_calls: [{
                  index: 0,
                  id: tc.id,
                  type: "function",
                  function: { name: tc.function.name, arguments: tc.function.arguments }
                }]
              },
              finish_reason: "tool_calls"
            }]
          };
          res.write(`data: ${JSON.stringify(chunk2)}\n\n`);
        }

        res.write("data: [DONE]\n\n");
        res.end();
      } else {
        // Non-streaming JSON response
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({
          id: `chatcmpl-${step}`,
          object: "chat.completion",
          created: Math.floor(Date.now() / 1000),
          model: "mock-qwen",
          choices: [{
            index: 0,
            message: {
              role: "assistant",
              content,
              tool_calls: toolCalls.length > 0 ? toolCalls : undefined
            },
            finish_reason: toolCalls.length > 0 ? "tool_calls" : "stop"
          }],
          usage: { prompt_tokens: 100, completion_tokens: 30, total_tokens: 130 }
        }));
      }
      return;
    }

    // Default 404
    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Not found", path: url }));
  });
});

function tryParseJson(str) {
  try { return JSON.parse(str); } catch { return null; }
}

server.listen(PORT, "127.0.0.1", () => {
  console.log(`Mock LLM Server listening on http://127.0.0.1:${PORT}`);
});

