#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LOG_DIR="${SCRIPT_DIR}/../logs"
mkdir -p "$LOG_DIR"

QA_RUN_DIR="/var/tmp/nexus-qa-v111-run"
HOME_QA="${QA_RUN_DIR}/home-qa"
mkdir -p "$HOME_QA"

echo "=== [AREA 8] Git Integration Conflicts, Worktree Retention & Failure Independence ==="

export HOME="$HOME_QA"
export NEXUS_PREFIX="${QA_RUN_DIR}/home-fresh/.local"
export PATH="${NEXUS_PREFIX}/bin:${PATH}"
export LOCAL_LLM_ENDPOINT="http://127.0.0.1:19280/v1"
export LOCAL_LLM_MODEL="mock-qwen"

CONFLICT_REPO="${QA_RUN_DIR}/conflict-repo"
rm -rf "$CONFLICT_REPO"
mkdir -p "$CONFLICT_REPO"
cd "$CONFLICT_REPO"
git init -q
echo "Base content line 1" > file.txt
echo "Base content line 2" >> file.txt
git add file.txt
git commit -qm "Base commit"

# 1. SC-GIT-04: Worktree Retention Contract
echo "--> Testing worktree retention when unit has untracked files..."
node --input-type=module -e '
  import fs from "fs";
  import path from "path";
  import { execSync } from "child_process";
  import { OperationGitController } from "'"${NEXUS_PREFIX}"'/lib/nexus/v1.1.1/lib/cli/dist/core/operation_git.js";
  import { newOperation } from "'"${NEXUS_PREFIX}"'/lib/nexus/v1.1.1/lib/cli/dist/core/operation.js";

  const repo = "'"${CONFLICT_REPO}"'";
  const controller = new OperationGitController(repo);
  const op = newOperation("op-retention", "Worktree retention test", [
    { id: "dirty-unit", role: "implementer", prompt: "leave dirty file" }
  ], [
    { id: "res1", endpoint: "http://127.0.0.1:19280/v1", model: "m", provider: "local", capabilities: ["tools"], rank: 0 }
  ], Date.now());

  const unit = op.units[0];
  const { worktreePath, branch } = controller.createUnitWorktree(op, unit);
  console.log("Created unit worktree at:", worktreePath);

  // Create an untracked file inside unit worktree
  fs.writeFileSync(path.join(worktreePath, "untracked.tmp"), "untracked data");

  // Dispose unit
  const disposition = controller.disposeUnit(op, unit, "completed");
  console.log("Unit disposition:", disposition);

  if (disposition && disposition.retained) {
    console.log("PASS: Worktree retained due to untracked file:", disposition.path);
    if (!fs.existsSync(worktreePath)) {
      console.error("FAIL: Expected worktree directory to be retained on disk!");
      process.exit(1);
    }
  } else {
    console.error("FAIL: Expected worktree to be retained, got:", disposition);
    process.exit(1);
  }

  // Clean up retained worktree
  controller.cleanWorktree(worktreePath);
' 2>&1 | tee "${LOG_DIR}/08_worktree_retention.log"

echo "PASS: SC-GIT-04: Worktree retention policy verified"

# 2. SC-GIT-03: Serialized Integration & Merge Conflict Handling
echo "--> Testing serialized integration merge conflict detection..."
node --input-type=module -e '
  import fs from "fs";
  import path from "path";
  import { execSync } from "child_process";
  import { OperationGitController } from "'"${NEXUS_PREFIX}"'/lib/nexus/v1.1.1/lib/cli/dist/core/operation_git.js";
  import { newOperation } from "'"${NEXUS_PREFIX}"'/lib/nexus/v1.1.1/lib/cli/dist/core/operation.js";

  const repo = "'"${CONFLICT_REPO}"'";
  const controller = new OperationGitController(repo);
  const op = newOperation("op-conflict", "Conflict test", [
    { id: "u1", role: "implementer", prompt: "change line 1" },
    { id: "u2", role: "implementer", prompt: "conflicting change line 1" }
  ], [
    { id: "res1", endpoint: "http://127.0.0.1:19280/v1", model: "m", provider: "local", capabilities: ["tools"], rank: 0 }
  ], Date.now());

  controller.ensureIntegration(op);

  // Unit 1
  const u1 = op.units[0];
  const wt1 = controller.createUnitWorktree(op, u1);
  fs.writeFileSync(path.join(wt1.worktreePath, "file.txt"), "Unit 1 modification\nBase line 2\n");
  const receipt1 = controller.integrateUnit(op, u1, { candidateDigest: "sha256-test1" });
  console.log("Unit 1 receipt outcome:", receipt1.outcome, "integratedCommit:", receipt1.integratedCommit);

  // Unit 2 creates conflicting modification on same lines
  const u2 = op.units[1];
  const wt2 = controller.createUnitWorktree(op, u2);
  fs.writeFileSync(path.join(wt2.worktreePath, "file.txt"), "Unit 2 CONFLICTING modification\nBase line 2\n");

  const receipt2 = controller.integrateUnit(op, u2, { candidateDigest: "sha256-test2" });
  console.log("Unit 2 receipt outcome:", receipt2.outcome, "conflictedFiles:", receipt2.conflictedFiles);

  if (receipt2.outcome === "CONFLICT") {
    console.log("PASS: Merge conflict cleanly caught with outcome CONFLICT and conflicted files identified");
  } else {
    console.error("FAIL: Expected receipt outcome CONFLICT, got:", receipt2.outcome);
    process.exit(1);
  }
' 2>&1 | tee "${LOG_DIR}/08_git_conflict.log"

echo "PASS: SC-GIT-03: Merge conflict caught cleanly without corrupting repo"

echo "=== [AREA 8] Complete: All checks PASSED ==="

